def main():
    # Binary tree as dict-of-children adjacency (parent -> [children])
    children = {
        "A": ["B", "C"],
        "B": ["D", "E"],
        "C": ["F", "G"],
        "D": [], "E": [], "F": [], "G": [],
    }
    root = "A"

    depth = {root: 0}
    q = deque([root])
    while q:
        cur = q.popleft()
        for ch in children[cur]:
            depth[ch] = depth[cur] + 1
            q.append(ch)

    for name in sorted(depth):
        print(f"{name}: {depth[name]}")


if __name__ == "__main__":
